CREATE TABLE DEPARTAMENTOS (ID INTEGER NOT NULL PRIMARY KEY, NOMBRE VARCHAR(60));
CREATE TABLE PRODUCTOS (ID INTEGER NOT NULL PRIMARY KEY, CODIGO VARCHAR(60), DESCRIPCION VARCHAR(120), TVENTA VARCHAR(1), PCOSTO NUMERIC(18,4), PVENTA NUMERIC(18,4), MAYOREO NUMERIC(18,4), PFINAL NUMERIC(18,4), DEPT INTEGER, USA_INVENTARIO CHAR(1), DINVENTARIO NUMERIC(18,4), DINVMINIMO NUMERIC(18,4), DINVMAXIMO NUMERIC(18,4), ELIMINADO_EN TIMESTAMP);
CREATE TABLE CLIENTES (ID INTEGER NOT NULL PRIMARY KEY, NOMBRE VARCHAR(120), DIRECCION VARCHAR(200), TELEFONO VARCHAR(40), CORREO VARCHAR(80), LIMITE_CREDITO NUMERIC(18,2), SALDO NUMERIC(18,2), CREDITO_ILIMITADO CHAR(1), ELIMINADO_EN TIMESTAMP);
CREATE TABLE VENTATICKETS (ID INTEGER NOT NULL PRIMARY KEY, TOTAL NUMERIC(18,2), VENDIDO_EN TIMESTAMP, ESTA_CANCELADO CHAR(1));
